-- Scarlet Halls: Harlan exit through Koegler. Loot is deferred.
DELETE FROM `creature` WHERE `guid` BETWEEN 8300128 AND 8300244;
DELETE FROM `creature_addon` WHERE `guid` BETWEEN 8300128 AND 8300244;
-- Source template addon visuals are applied only to these spawns.
DELETE FROM `waypoint_data` WHERE `id` BETWEEN 83001280 AND 83002440;
DELETE FROM `gameobject` WHERE `guid` BETWEEN 910024 AND 910028;

