UPDATE `creature_template` SET `ScriptName` = 'boss_flameweaver_koegler' WHERE `entry` = 59150 AND `ScriptName` IN ('', 'boss_flameweaver_koegler') AND `AIName` = '';
UPDATE `creature_template` SET `ScriptName` = 'npc_dragon_breath_targeting' WHERE `entry` = 59198 AND `ScriptName` IN ('', 'npc_dragon_breath_targeting') AND `AIName` = '';
UPDATE `creature_template` SET `ScriptName` = 'npc_scarlet_hooded_crusader' WHERE `entry` = 64738 AND `ScriptName` IN ('', 'npc_scarlet_hooded_crusader') AND `AIName` = '';

DELETE FROM `creature_text` WHERE `entry` IN (59150, 64738);

DELETE FROM `spell_script_names` WHERE (`spell_id` = 113364 AND `ScriptName` = 'spell_koegler_book_burner') OR (`spell_id` = 113641 AND `ScriptName` = 'spell_dragon_breath_sc');

