INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(59150, 0, 0, 'Everything must burn. None shall know of the Scarlet Crusade\'s shame!', 14, 0, 100, 0, 0, 29524, 'Koegler intro'),
(59150, 1, 0, 'You, too, shall be charred to ash!', 14, 0, 100, 0, 0, 29522, 'Koegler aggro'),
(59150, 2, 0, 'Purged by fire!', 14, 0, 100, 0, 0, 29528, 'Koegler dragon breath'),
(59150, 3, 0, '|TInterface\\Icons\\ability_warlock_inferno.blp:20|t%s begins to cast |cFFFF0000|Hspell:113364|h[Book Burner]|h|r!', 41, 0, 100, 0, 0, 0, 'Koegler book burner'),
(59150, 4, 0, '|TInterface\\Icons\\inv_misc_head_dragon_01.blp:20|t%s begins to cast |cFFFF0000|Hspell:113653|h[Greater Dragon\'s Breath]|h|r!', 41, 0, 100, 0, 0, 0, 'Koegler dragon breath'),
(59150, 5, 0, 'My fire... has gone out..', 14, 0, 100, 0, 0, 29523, 'Koegler death'),
(64738, 0, 0, 'There are a lot of corpses out there.  Nicely done, $p.', 12, 0, 100, 0, 0, 0, 'Hooded Crusader intro'),
(64738, 1, 0, 'Did you get the codex?', 12, 0, 100, 0, 0, 0, 'Hooded Crusader codex');
